/* ------------------------------------------------------------
   Inbox hook — keeps everything for the mail feature inside
   data.js, so index.html / app.js / styles.css stay untouched.
   Clicking the chat icon in the header opens the inbox.
   ------------------------------------------------------------ */
document.addEventListener("DOMContentLoaded", function () {
  var openId = null;

  var css = document.createElement("style");
  css.textContent =
    ".icon-btn{position:relative}" +
    ".mail-dot{position:absolute;top:4px;right:4px;width:9px;height:9px;border-radius:50%;background:#e0443a}" +
    ".mail-row{cursor:pointer}.mail-row:hover td{background:#eef3f8 !important}" +
    ".mail-subject{font-size:20px;margin:18px 0 12px;color:#2a3548}" +
    ".mail-meta{font-size:14px;line-height:1.7;color:#444;border-bottom:1px solid #d7dde3;padding-bottom:12px;margin-bottom:16px}" +
    ".mail-body{white-space:pre-wrap;font-size:14.5px;line-height:1.6;color:#222;max-width:820px}";
  document.head.appendChild(css);

  function esc(s) {
    return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  function mailHtml() {
    if (openId !== null) {
      var m = MAILS.filter(function (x) { return x.id === openId; })[0];
      var body = esc(m.body).replace(/(https?:\/\/[^\s]+)/g,
        '<a href="$1" target="_blank" rel="noopener">$1</a>');
      return '<button class="btn-primary" onclick="closeMail()">&#8592; Inbox</button>' +
        '<h2 class="mail-subject">' + esc(m.subject) + '</h2>' +
        '<div class="mail-meta"><div><b>From:</b> ' + esc(m.fromName) + ' &lt;' + m.from + '&gt;</div>' +
        '<div><b>To:</b> ' + m.to + '</div><div><b>Date:</b> ' + m.date + '</div></div>' +
        '<div class="mail-body">' + body + '</div>';
    }
    var rows = MAILS.map(function (m) {
      return '<tr class="mail-row" onclick="openMail(' + m.id + ')"><td><b>' + esc(m.fromName) +
        '</b></td><td>' + esc(m.subject) + '</td><td style="white-space:nowrap">' + m.date + '</td></tr>';
    }).join("");
    return '<table class="data-table"><thead><tr><th>From</th><th>Subject</th><th>Date</th></tr></thead><tbody>' +
      rows + '</tbody></table>';
  }

  window.openMail = function (id) { openId = id; render(); };
  window.closeMail = function () { openId = null; render(); };

  // Wrap the existing content renderer: show the inbox when the mail view is active
  var originalRenderContent = renderContent;
  renderContent = function () {
    if (state.currentModule === "__mail__") {
      document.getElementById("content-header").textContent = "Messages";
      document.getElementById("content-body").innerHTML = mailHtml();
      return;
    }
    originalRenderContent();
  };

  var btn = document.querySelector(".icon-btn");
  if (btn) {
    var dot = document.createElement("span");
    dot.className = "mail-dot";
    btn.appendChild(dot);
    btn.addEventListener("click", function () {
      closeAllPopovers();
      state.currentModule = "__mail__";
      state.currentView = null;
      openId = null;
      render();
    });
  }
});
